-- Fake Resolve for test_resolve_markers.py: runs menu scripts generated by tools/resolve_markers.py
-- in Resolve's own Lua (fuscript.exe) under the same sandbox as Resolve's Workspace → Scripts menu
-- (no io, dofile, require, os.execute, debug) and prints the markers that ended up on each clip.
-- Environment: CT_DIR (folder with the videos), CT_SCRIPTS (menu scripts to run, separated by "|").
local dir, scripts = os.getenv("CT_DIR"), os.getenv("CT_SCRIPTS")
local real = { io = io, loadfile = loadfile, print = print }

local function clip(name, fps, frames)
    local c = { markers = {}, path = dir .. "\\" .. name, name = name }
    function c:GetName() return self.name end
    function c:GetClipProperty(key)
        if key == "File Path" then return self.path end
        if key == "FPS" then return fps end
        if key == "Frames" then return tostring(frames) end
    end
    function c:GetMediaPoolItem() return self end
    function c:GetLeftOffset() return 0 end
    function c:GetMarkers()
        local t = {}
        for k, v in pairs(self.markers) do t[k] = v end
        return t
    end
    function c:AddMarker(frame, color, name, note, duration, custom)
        if self.markers[frame] then return false end
        self.markers[frame] = { color = color, name = name, note = note, duration = duration, customData = custom }
        return true
    end
    function c:DeleteMarkerAtFrame(frame)
        if not self.markers[frame] then return false end
        self.markers[frame] = nil
        return true
    end
    return c
end

local gopro = clip("GX010123.MP4", "59.94", 3600)
local proxy = clip("DJI_0001.LRF", 30, 900)
local other = clip("C0001.MP4", 25, 500)
local title = { GetName = function() return "Title" end, GetMediaPoolItem = function() return nil end }
gopro:AddMarker(100, "Green", "my own", "", 1, nil)              -- placed by hand: must stay

-- Resolve's lists are tables {[1] = a, [2] = b, ...} that may hold other fields (numbers) too
local function resolve_list(...)
    local t = { ... }
    t.n = #t
    return t
end

local timeline = {
    GetName = function() return "Selects Turkey" end,
    GetTrackCount = function(_, kind) return kind == "video" and 2 or 0 end,
    GetItemListInTrack = function(_, _, i)
        if i == 1 then return resolve_list(gopro, other, title) end
        return resolve_list(proxy)
    end,
}
local day2 = { GetClipList = function() return resolve_list(proxy) end,
               GetSubFolderList = function() return resolve_list() end }
local root = { GetClipList = function() return resolve_list(gopro) end,
               GetSubFolderList = function() return resolve_list(day2) end }
local project = { GetCurrentTimeline = function() return timeline end,
                  GetMediaPool = function() return { GetRootFolder = function() return root end } end }
resolve = { GetProjectManager = function() return { GetCurrentProject = function() return project end } end }

for script in scripts:gmatch("[^|]+") do
    local chunk = assert(real.loadfile(script))
    setfenv(chunk, getfenv(1))                      -- the harness's globals: resolve and the sandbox
    -- Resolve's sandbox
    io, dofile, loadfile, require, debug = nil, nil, nil, nil, nil
    os.execute, os.remove = nil, nil
    local ok, err = pcall(chunk)
    io, loadfile = real.io, real.loadfile
    if not ok then real.print("SCRIPT ERROR " .. tostring(err)) end
    local name = script:match("([^\\/]+)%.lua$")
    for _, c in ipairs({ gopro, proxy, other }) do
        local frames = {}
        for f in pairs(c.markers) do frames[#frames + 1] = f end
        table.sort(frames)
        for _, f in ipairs(frames) do
            local m = c.markers[f]
            real.print(table.concat({ "MARKER", name, c.name, f, m.color, m.name, m.duration, m.note or "" }, "|"))
        end
    end
end
